    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] cost = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            cost[i] = (long) in.nval;
        }
        int[][] tag = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                in.nextToken();
                tag[i][j] = (int) in.nval;
            }
        }
        System.out.println(minCost(n, m, cost, tag));
